{"path": "src/App.tsx", "content": "import React, { useEffect, useState } from 'react';
import { AppState, AppStateStatus } from 'react-native';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { StatusBar } from 'expo-status-bar';
import { ActivityIndicator, PaperProvider } from 'react-native-paper';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import Navigation from './navigation';
import { acceptPolicy, getPolicyAcceptance, policyAccepted } from './lib/policy';
import { getStore } from './lib/storage';
import PolicyScreen from './screens/PolicyScreen';
import { theme } from './theme';
import { getAppLockEnabled } from './lib/settings';
import { authenticate } from './lib/appLock';

// Every Paper icon goes through this renderer. Icons sit inside labelled controls, so the glyph is decorative
// and hidden from screen readers (Paper's default web icon is an unlabelled role="img", which fails axe).
const paperSettings = { icon: (props: React.ComponentProps<typeof MaterialCommunityIcons>) => <MaterialCommunityIcons {...props} aria-hidden /> };

type Gate = 'loading' | 'policy' | 'ready';

export default function App() {
  const [gate, setGate] = useState<Gate>('loading');
  const [locked, setLocked] = useState<boolean>(false);

  // Initial policy check
  useEffect(() => {
    getPolicyAcceptance(getStore())
      .then((a) => setGate(policyAccepted(a) ? 'ready' : 'policy'))
      .catch(() => setGate('policy'));
  }, []);

  // Check app lock after policy is ready (initial launch)
  useEffect(() => {
    if (gate === 'ready') {
      (async () => {
        const enabled = await getAppLockEnabled();
        if (enabled) {
          const ok = await authenticate();
          setLocked(!ok);
        }
      })();
    }
  }, [gate]);

  // Re‑authenticate whenever the app returns to the foreground
  useEffect(() => {
    const subscription = AppState.addEventListener('change', async (nextState: AppStateStatus) => {
      if (nextState === 'active' && gate === 'ready') {
        const enabled = await getAppLockEnabled();
        if (enabled) {
          const ok = await authenticate();
          setLocked(!ok);
        } else {
          setLocked(false);
        }
      }
    });
    return () => {
      subscription.remove();
    };
  }, [gate]);

  const accept = async () => {
    await acceptPolicy(getStore());
    setGate('ready');
  };

  // Show loading while checking policy or when locked after a successful auth check fails
  if (gate === 'loading' || (gate === 'ready' && locked)) {
    return (
      <SafeAreaProvider>
        <PaperProvider theme={theme} settings={paperSettings}>
          <StatusBar style="dark" />
          <ActivityIndicator style={{ flex: 1 }} accessibilityLabel="Loading" />
        </PaperProvider>
      </SafeAreaProvider>
    );
  }

  return (
    <SafeAreaProvider>
      <PaperProvider theme={theme} settings={paperSettings}>
        <StatusBar style="dark" />
        {gate === 'policy' ? (
          <PolicyScreen onAccept={accept} />
        ) : (
          <Navigation />
        )}
      </PaperProvider>
    </SafeAreaProvider>
  );
}
"}

{"path": "src/screens/DashboardScreen.tsx", "content": "import React, { useEffect, useState } from 'react';
import { ActivityIndicator, Snackbar, Text } from 'react-native-paper';
import { FlatList, View } from 'react-native';
import { useNavigation, useRoute, NavigationProp, RouteProp } from '@react-navigation/native';
import { EmptyState, Screen, SummaryCard } from '../components/ui';
import { getStore } from '../lib/storage';
import { Receipt, MileageEntry } from '../lib/models';
import { getAllReceipts } from '../lib/receiptStore';
import { getAllMileageEntries } from '../lib/mileageStore';
import { computeTotals } from '../lib/finance';
import { totalMileageDeduction } from '../lib/mileage';
import { getTaxRate } from '../lib/settings';
import ReceiptCard from '../components/ui/ReceiptCard';
import { consumeSnack } from '../lib/uiState';
import SimpleAddButtons from '../components/ui/SimpleAddButtons';
import { space } from '../../theme';

type DashboardRouteParams = {};

export default function DashboardScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const route = useRoute<RouteProp<Record<string, DashboardRouteParams>, string>>();
  const [loading, setLoading] = useState(true);
  const [receipts, setReceipts] = useState<Receipt[]>([]);
  const [mileageEntries, setMileageEntries] = useState<MileageEntry[]>([]);
  const [mileageDeduction, setMileageDeduction] = useState<number>(0);
  const [tax, setTax] = useState<number>(0);
  const [snack, setSnack] = useState<string>('');

  const load = async () => {
    setLoading(true);
    const store = getStore();
    const recs = await getAllReceipts(store);
    const miles = await getAllMileageEntries(store);
    setReceipts(recs);
    setMileageEntries(miles);
    const deduction = await totalMileageDeduction(miles);
    setMileageDeduction(deduction);
    const taxRate = await getTaxRate(store);
    const totals = computeTotals(recs);
    const taxable = Math.max(0, totals.income - totals.expenses - deduction);
    setTax(taxable * taxRate);
    setLoading(false);
    const pending = consumeSnack();
    if (pending) setSnack(pending);
  };

  useEffect(() => {
    const unsubscribe = navigation.addListener('focus', load);
    return unsubscribe;
  }, [navigation]);

  if (loading) {
    return <ActivityIndicator style={{ flex: 1 }} accessibilityLabel="Loading" />;
  }

  const totals = computeTotals(receipts);

  const empty = receipts.length === 0 && mileageEntries.length === 0;

  return (
    <Screen title="Dashboard" wide>
      {empty ? (
        <EmptyState
          icon="inbox-outline"
          title="Nothing here yet"
          body="Add a receipt or mileage entry to start tracking your finances."
        />
      ) : (
        <View style={{ gap: 16 }}>
          <View style={{ flexDirection: 'row', gap: 8, flexWrap: 'wrap' }}>
            <SummaryCard label="Income" value={`$${totals.income.toFixed(2)}`} />
            <SummaryCard label="Expenses" value={`$${totals.expenses.toFixed(2)}`} />
            <SummaryCard label="Mileage deduction" value={`$${mileageDeduction.toFixed(2)}`} />
            <SummaryCard label="Estimated tax" value={`$${tax.toFixed(2)}`} />
          </View>
          <Text variant="titleMedium" style={{ marginTop: 8, marginBottom: 4 }}>Recent activity</Text>
          <FlatList
            data={receipts.slice(0, 5)}
            keyExtractor={(item) => item.id}
            renderItem={({ item }) => <ReceiptCard receipt={item} />}
          />
        </View>
      )}
      {snack ? (
        <Snackbar
          visible={true}
          onDismiss={() => setSnack('')}
          duration={3000}
          style={{ bottom: space(14) }}
