{"path":"src/screens/BackupPassphraseScreen.tsx","content":"import React, { useState } from 'react';
import { HelperText } from 'react-native-paper';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { FormField, PrimaryButton, Screen } from '../components/ui';
import { createBackup } from '../lib/backup';
import { utf8 } from '../lib/crypto';
import { saveAndShare } from '../lib/files';
import { getStore } from '../lib/storage';

const MIN_LENGTH = 8;
/**
 * Validate passphrase: at least MIN_LENGTH characters and at least three of the four character classes.
 */
function validatePassphrase(p: string): string | null {
  if (p.length < MIN_LENGTH) return `Use at least ${MIN_LENGTH} characters.`;
  const classes = [/[A-Z]/, /[a-z]/, /[0-9]/, /[^A-Za-z0-9]/].filter((re) => re.test(p)).length;
  if (classes < 3) return 'Use at least three character classes (uppercase, lowercase, digit, symbol).';
  return null;
}

export default function BackupPassphraseScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [pass1, setPass1] = useState('');
  const [pass2, setPass2] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);

  const create = async () => {
    // Ensure passphrases match and meet policy.
    if (pass1 !== pass2) return setError("The passphrases don't match.");
    const validation = validatePassphrase(pass1);
    if (validation) return setError(validation);
    setError('');
    setBusy(true);
    try {
      const backup = await createBackup(getStore(), pass1);
      // Share backup asynchronously (fire‑and‑forget)
      saveAndShare(`finance-backup-${new Date().toISOString().slice(0, 10)}.backup`, utf8(backup)).catch(() => {});
      navigation.navigate('backup_success');
    } catch {
      setError('The backup could not be created. Please try again.');
    } finally {
      setBusy(false);
    }
  };

  // Show any validation error for the primary passphrase.
  const fieldError = error || (pass1 && pass2 && validatePassphrase(pass1) ? validatePassphrase(pass1) : null);

  // Enable button only when validation passes and not busy.
  const canCreate = !busy && pass1 && pass2 && pass1 === pass2 && !validatePassphrase(pass1);

  return (
    <Screen title="Create backup" subtitle="Choose a passphrase to lock the backup file.">
      <FormField
        label="Backup passphrase"
        value={pass1}
        onChangeText={setPass1}
        secureTextEntry
        autoCapitalize="none"
        hint={`At least ${MIN_LENGTH} characters`}
        accessibilityLabel="Backup passphrase"
      />
      <FormField
        label="Confirm passphrase"
        value={pass2}
        onChangeText={setPass2}
        secureTextEntry
        autoCapitalize="none"
        accessibilityLabel="Confirm passphrase"
      />
      {fieldError ? <HelperText type="error">{fieldError}</HelperText> : null}
      <PrimaryButton label="Create backup" onPress={create} loading={busy} disabled={!canCreate} />
    </Screen>
  );
}
"}

{"path": "src/lib/storage/device.web.ts", "content": "// Web implementation of storage using in-memory store.
import type { KeyProvider, RawStore } from './types';
import { createMemoryRawStore } from './memory';

/** Key provider that generates a fresh random key each call (no persistence). */
export function createDeviceKeyProvider(): KeyProvider {
  return {
    async getKey() {
      // Generate a new random key each time; data will be inaccessible after page reload,
      // which is acceptable for the web fallback where no secure persistent storage is available.
      const { randomBytes } = await import('./crypto');
      return randomBytes(32);
    },
  };
}

let rawStoreInstance: RawStore | null = null;

/** Return a persistent in‑memory raw store for the session. */
export function createDeviceRawStore(): RawStore {
  if (!rawStoreInstance) {
    rawStoreInstance = createMemoryRawStore();
  }
  return rawStoreInstance;
}
"}

{"path": "src/lib/receiptStore.ts", "content": "// Thin wrapper around Store for the "receipts" collection.
import type { Store, StoredRecord } from './storage/types';
import type { Receipt } from './models';

const MAX_RECEIPTS = 10000;

export async function getAllReceipts(store: Store): Promise<Receipt[]> {
  return store.list<Receipt>('receipts');
}

export async function addReceipt(store: Store, receipt: Receipt): Promise<void> {
  const existing = await store.list<Receipt>('receipts');
  if (existing.length >= MAX_RECEIPTS) {
    throw new Error('Maximum number of receipts reached');
  }
  // Cast to StoredRecord to satisfy type constraints.
  await store.put('receipts', receipt as unknown as StoredRecord);
}
"}

{"path": "src/lib/mileageStore.ts", "content": "// Thin wrapper around Store for the "mileage" collection.
import type { Store, StoredRecord } from './storage/types';
import type { MileageEntry } from './models';

const MAX_MILEAGE_ENTRIES = 5000;

export async function getAllMileageEntries(store: Store): Promise<MileageEntry[]> {
  return store.list<MileageEntry>('mileage');
}

export async function addMileageEntry(store: Store, entry: MileageEntry): Promise<void> {
  const existing = await store.list<MileageEntry>('mileage');
  if (existing.length >= MAX_MILEAGE_ENTRIES) {
    throw new Error('Maximum number of mileage entries reached');
  }
  await store.put('mileage', entry as unknown as StoredRecord);
}
"}

{"path":"src/screens/ReceiptEntryScreen.tsx","content":"import React, { useState } from 'react';
import { View } from 'react-native';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { PrimaryButton, Screen, FormField, ChoiceField } from '../components/ui';
import { addReceipt } from '../lib/receiptStore';
import { getStore } from '../lib/storage';
import { Receipt, ReceiptType } from '../lib/models';
import { Snackbar } from 'react-native-paper';
import { setPendingSnack } from '../lib/uiState';
import ReceiptImagePicker from '../components/ui/ReceiptImagePicker';
import { v4 as uuidv4 } from 'uuid';

export default function ReceiptEntryScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [category, setCategory] = useState('');
  const [type, setType] = useState<ReceiptType>('expense');
  const [notes, setNotes] = useState('');
  const [photoUri, setPhotoUri] = useState<string | undefined>(undefined);
  const [error, setError] = useState<string>('');
  const [saving, setSaving] = useState(false);

  const validate = () => {
    if (!amount) return 'Enter a positive amount.';
    const amt = Number(amount);
    if (isNaN(amt) || amt <= 0) return 'Enter a positive amount.';
    if (amt > 1000000) return 'Amount must be less than 1,000,000.';
    // limit to 9 digits and max two decimal places
    if (!/^\d{1,9}(\.\d{1,2})?$/.test(amount)) return 'Amount must have up to 9 digits and 2 decimals.';
    if (!date) return 'Select a date.';
    if (!category) return 'Choose a category.';
    if (!type) return 'Select expense or income.';
    return '';
  };

  const onSave = async () => {
    const err = validate();
    if (err) {
      setError(err);
      return;
    }
    setError('');
    setSaving(true);
    const receipt: Receipt = {
      id: uuidv4(),
      amount: Number(amount),
      date,
      category,
      type,
      notes,
      photoUri,
    };
    try {
      await addReceipt(getStore(), receipt);
      setPendingSnack('Receipt saved');
      navigation.navigate('Main', { screen: 'Dashboard' });
    } catch (e) {
      setError('Unable to save receipt. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  const canSave = !saving && validate() === '';

  return (
    <Screen title="Add receipt">
      <View style={{ gap: 12 }}>
        <ReceiptImagePicker photoUri={photoUri} onChange={setPhotoUri} />
        <FormField label="Amount" value={amount} onChangeText={setAmount} keyboardType="numeric" />
        <FormField label="Date" value={date} onChangeText={setDate} placeholder="YYYY-MM-DD" />
        <FormField label="Category" value={category} onChangeText={setCategory} />
        <ChoiceField<ReceiptType>
          label="Type"
          value={type}
          onChange={setType}
          options={[{ value: 'expense', label: 'Expense' }, { value: 'income', label: 'Income' }]}
        />
        <FormField label="Notes" value={notes} onChangeText={setNotes} multiline />
        {error ? <Snackbar visible={true} onDismiss={() => setError('')} duration={3000}>{error}</Snackbar> : null}
        <PrimaryButton label="Save receipt" onPress={onSave} loading={saving} disabled={!canSave} />
      </View>
    </Screen>
  );
}
"}

{"path":"src/screens/ReceiptsScreen.tsx","content":"import React, { useEffect, useState } from 'react';
import { ActivityIndicator, FlatList, View } from 'react-native';
import { useNavigation, useRoute, NavigationProp } from '@react-navigation/native';
import { EmptyState, PrimaryButton, Screen } from '../components/ui';
import { getStore } from '../lib/storage';
import { Receipt } from '../lib/models';
import { getAllReceipts } from '../lib/receiptStore';
import ReceiptCard from '../components/ui/ReceiptCard';
import SimpleAddButtons from '../components/ui/SimpleAddButtons';

export default function ReceiptsScreen() {
  const navigation = useNavigation<NavigationProp<any>>();
  const route = useRoute<any>();
  const [loading, setLoading] = useState(true);
  const [receipts, setReceipts] = useState<Receipt[]>([]);

  const load = async () => {
    setLoading(true);
    const recs = await getAllReceipts(getStore());
    setReceipts(recs);
    setLoading(false);
  };

  useEffect(() => {
    const unsubscribe = navigation.addListener('focus', load);
    return unsubscribe;
  }, [navigation]);

  if (loading) {
    return <ActivityIndicator style={{ flex: 1 }} accessibilityLabel="Loading" />;
  }

  const empty = receipts.length === 0;

  return (
    <Screen title="Receipts">
      {empty ? (
        <EmptyState
          icon="receipt-outline"
          title="No receipts recorded"
          body="Tap the + button to add your first receipt."
          actionLabel="Add receipt"
          onAction={() => navigation.navigate('ReceiptEntry')}
        />
      ) : (
        <FlatList
          data={receipts}
          keyExtractor={(item) => item.id}
          renderItem={({ item }) => <ReceiptCard receipt={item} />}
        />
      )}
      <SimpleAddButtons />
    </Screen>
  );
}
"}

{"path": "src/lib/backup.ts", "content": "import type { Store } from './storage/types';
import { keepingPolicy } from './dataReset';
import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import { deriveKey, encrypt, decrypt, toBase64, fromBase64, utf8, fromUtf8, randomBytes } from './crypto';
import type { Receipt, MileageEntry } from './models';
import * as FileSystem from 'expo-file-system';
import { Paths } from 'expo-file-system';

/** Create an encrypted backup of all data, including receipt photos.
 * Returns a base64‑encoded string representing the encrypted payload.
 */
export async function createBackup(store: Store, passphrase: string): Promise<string> {
  const receipts: Receipt[] = await getAllReceipts(store);
  const mileage: MileageEntry[] = await getAllMileageEntries(store);
  const receiptsWithPhotos = await Promise.all(
    receipts.map(async (r) => {
      if (r.photoUri) {
        try {
          const b64 = await FileSystem.readAsStringAsync(r.photoUri, { encoding: FileSystem.EncodingType.Base64 });
          return { ...r, photoData: b64 };
        } catch {
          return { ...r };
        }
      }
      return { ...r };
    })
  );
  const payload = JSON.stringify({ receipts: receiptsWithPhotos, mileage });
  const salt = randomBytes(16);
  const key = deriveKey(passphrase, salt);
  const encrypted = encrypt(key, utf8(payload));
  const combined = new Uint8Array(salt.length + encrypted.length);
  combined.set(salt, 0);
  combined.set(encrypted, salt.length);
  return toBase64(combined);
}

/** Restore data from an encrypted backup blob.
 * Throws an error with a friendly message if the passphrase is wrong or the file is corrupted.
 */
export async function restoreBackup(store: Store, backupBlob: string, passphrase: string): Promise<void> {
  const combined = fromBase64(backupBlob);
  if (combined.length < 16) throw new Error('Invalid backup file');
  const salt = combined.subarray(0, 16);
  const ciphertext = combined.subarray(16);
  const key = deriveKey(passphrase, salt);
  let decrypted: string;
  try {
    decrypted = fromUtf8(decrypt(key, ciphertext));
  } catch {
    throw new Error('Invalid passphrase or corrupted backup file');
  }
  const data = JSON.parse(decrypted) as { receipts: (Receipt & { photoData?: string })[]; mileage: MileageEntry[] };

  // Clean any existing cached photos before restoring new ones.
  const cacheDir = Paths.cache.uri;
  try {
    const entries = await FileSystem.readDirectoryAsync(cacheDir);
    await Promise.all(entries.map((e) => FileSystem.deleteAsync(`${cacheDir}${e}`, { idempotent: true })));
  } catch {
    // ignore errors – directory may be empty or inaccessible.
  }

  await keepingPolicy(store, async () => {
    await store.clearAll();
    for (const r of data.receipts) {
      const { photoData, ...rest } = r as any;
      await store.put('receipts', rest as any);
      if (photoData) {
        const uri = `${cacheDir}${rest.id}_photo`;
        try {
          await FileSystem.writeAsStringAsync(uri, photoData, { encoding: FileSystem.EncodingType.Base64 });
          await store.put('receipts', { ...rest, photoUri: uri } as any);
        } catch {}
      }
    }
    for (const m of data.mileage) {
      await store.put('mileage', m as any);
    }
  });
}
"}

