    },
    {
      "element": "Date and Category inputs",
      "issue": "They look identical to free-text inputs but open pickers, so there is no affordance and no way to tell they are tappable.",
      "fix": "Render them as read-only pressable fields: <TextInput mode=\"outlined\" editable={false} right={<TextInput.Icon icon=\"calendar\" />} for Date and right={<TextInput.Icon icon=\"menu-down\" />} for Category, wrapped in a Pressable that opens the DatePicker / Menu. Default Date to today so the field is pre-filled.",
      "shared": true
    },
    {
      "element": "\"Type\" selector (Expense / Income)",
      "issue": "Custom two-button toggle with a tiny teal label that reads like an error, selected state is a pale fill with no checkmark, and it is not visually grouped with its label.",
      "fix": "Replace with Paper <SegmentedButtons value={type} onValueChange={setType} buttons={[{value:'expense',label:'Expense',icon:'arrow-down'},{value:'income',label:'Income',icon:'arrow-up'}]} />, preceded by <Text variant=\"bodySmall\" style={{color: theme.colors.onSurfaceVariant, marginBottom: 8}}>Type</Text>, with marginBottom: 16 on the group.",
